[CmdletBinding(SupportsShouldProcess)]param([string]$RepositoryRoot=(Resolve-Path (Join-Path $PSScriptRoot '../..')),[Parameter(Mandatory)][string]$Version,[string]$PacCommand='pac')
$ErrorActionPreference='Stop'; Import-Module (Join-Path $PSScriptRoot 'Common/DeveloperPlatform.Common.psm1') -Force
Assert-CleanGitWorkingTree $RepositoryRoot; Push-Location $RepositoryRoot
try {if((git branch --show-current) -ne 'main'){throw 'Releases must be created from main.'};$cfg=Join-Path $RepositoryRoot 'powerplatform/scripts/DeveloperPlatform.psd1';(Get-Content $cfg -Raw) -replace "Version = '[^']+'","Version = '$Version'"|Set-Content $cfg -Encoding utf8;& (Join-Path $PSScriptRoot 'Build.ps1') -RepositoryRoot $RepositoryRoot -PacCommand $PacCommand;git add $cfg;git commit -m "chore(release): $Version";if($PSCmdlet.ShouldProcess("v$Version",'Create and push annotated tag')){git tag -a "v$Version" -m "Governance Portal $Version";git push origin main;git push origin "v$Version"}} finally {Pop-Location}
